		hoedown_buffer *header_work;
		hoedown_buffer *attr_work;
		size_t len;

		if (work.size) {
			size_t beg;
			i = work.size;
			work.size -= 1;

			while (work.size && data[work.size] != '\n')
				work.size -= 1;

			beg = work.size + 1;
